    steps: [['`tool_choice="auto"`', 'Default: LLM chooses text or tool(s)'], ['`tool_choice="required"`', 'Guarantees at least 1 tool call happens'], ['`tool_choice="none"`', 'Force final answer after budget exhausted'], ['Parallel Execution', 'Run returned tool calls concurrently with `asyncio.gather`']],
    jobUse: 'Cuts multi-lookup agent latency in half while forcing clean final answers on the last step.',
    mistake: 'Forgetting to set `tool_choice="none"` on the final budget step so the agent tries calling yet another tool.',
